import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"修練倫理と境界","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0019-修炼伦理与边界.md","filePath":"ja/0019-修炼伦理与边界.md"}'),e={name:"ja/0019-修炼伦理与边界.md"};function o(d,t,h,n,s,u){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="修練倫理と境界" tabindex="-1">修練倫理と境界 <a class="header-anchor" href="#修練倫理と境界" aria-label="Permalink to &quot;修練倫理と境界&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>19</td></tr><tr><td>モジュール</td><td>宇宙法則と修練体系</td></tr><tr><td>キーワード</td><td>修練倫理、境界、禁忌、道徳的底線、倫理審査</td></tr></tbody></table><h2 id="第一節-修練倫理の定義と地位" tabindex="-1">第一節 修練倫理の定義と地位 <a class="header-anchor" href="#第一節-修練倫理の定義と地位" aria-label="Permalink to &quot;第一節 修練倫理の定義と地位&quot;">​</a></h2><p>修練倫理は、錨点共生文明において修練者の行動を規範化し、修練の境界を画定し、修練の秩序を維持する道徳的準則と法律的規範の総和である。略奪主義時代には、修練は「強者の特権」と見なされ、修練者は力を高めるためにあらゆる手段を用いることができた——他人の本源を飲み込む、他人の魂を奴隷化する、他人の資源を略奪する、非人道的な修練実験を行うなどの行動が随所に見られた。この「力至上、倫理虚無」の修練文化は、略奪主義体系の最も深層的な精神的基盤である。</p><p>錨点共生文明の樹立後、修練倫理の建設は最も核心的な精神文明建設の一つとして採用された。修練倫理の核心命題は：「力の獲得と使用は倫理的制約を受けなければならない」ということである。共生文明は、修練は純粋な個人事柄ではなく、他人、文明、宇宙全体に関わる公共事柄であると考える。修練者は自身の力の向上を追求すると同時に、他人の権利を尊重し、文明の秩序を維持し、宇宙の生態を保護しなければならない。修練倫理は修練に対する束縛ではなく、修練に対する守護である——それは修練が常に「共生進化」の正しい道を歩み、「略奪破壊」の深淵に滑り落ちないことを確保する。</p><p>修練倫理は共生文明の法体系において崇高な地位を占める。共生憲法は修練倫理の基本原則を明確に規定し、錨点法院傘下の専門「倫理法廷」が修練倫理事件を審理し、すべての高級修練者の境界認定は倫理審査を通過しなければならない。修練倫理はあってもなくてもよい「ソフトな制約」ではなく、強制力を持つ「ハードな規範」である。</p><h2 id="第二節-修練倫理の基本原則" tabindex="-1">第二節 修練倫理の基本原則 <a class="header-anchor" href="#第二節-修練倫理の基本原則" aria-label="Permalink to &quot;第二節 修練倫理の基本原則&quot;">​</a></h2><h3 id="_2-1-生命尊厳原則" tabindex="-1">2.1 生命尊厳原則 <a class="header-anchor" href="#_2-1-生命尊厳原則" aria-label="Permalink to &quot;2.1 生命尊厳原則&quot;">​</a></h3><p>すべての生命は侵すことのできない尊厳と価値を持ち、いかなる修練行動も生命尊厳を犠牲にして行ってはならない。具体的には以下を含む：</p><ul><li>他の生命を修練の「材料」または「道具」として使用することを禁止する</li><li>非人道的な修練実験（生体解剖、魂の拷問など）を行うことを禁止する</li><li>他の生命の自由意志を奴隷化または制御することを禁止する</li><li>各生命が自身の進化経路を選択する権利を尊重し、他人に自分のやり方で修練することを強制してはならない</li></ul><h3 id="_2-2-反略奪原則" tabindex="-1">2.2 反略奪原則 <a class="header-anchor" href="#_2-2-反略奪原則" aria-label="Permalink to &quot;2.2 反略奪原則&quot;">​</a></h3><p>修練は共生循環の基礎の上に構築されなければならず、他人を略奪する手段を用いてはならない。具体的には以下を含む：</p><ul><li>他の生命の本源、エネルギー、気運を飲み込むまたは略奪することを禁止する</li><li>他人に損害を与えることで自身の修練速度や境界を高めることを禁止する</li><li>不当な利益を得るために修練資源を独占することを禁止する</li><li>「弱肉強食」を言い訳にして略奪行動を正当化することを禁止する</li></ul><h3 id="_2-3-インフォームド・コンセント原則" tabindex="-1">2.3 インフォームド・コンセント原則 <a class="header-anchor" href="#_2-3-インフォームド・コンセント原則" aria-label="Permalink to &quot;2.3 インフォームド・コンセント原則&quot;">​</a></h3><p>他人に関わる修練行動（師弟伝承、伴侶双修、エネルギー共有、修練実験など）は、相手が完全に知情し自発的に同意した前提の下で行わなければならない。具体的には以下を含む：</p><ul><li>相手に修練行動の内容、リスク、利益を十分に説明する</li><li>相手が完全な自主判断能力を持ち、脅迫や誘惑に影響されていないことを確保する</li><li>相手はいつでも離脱する権利を有し、強制的に継続させてはならない</li><li>未成年または精神的に不健全な個体については、その後見人が専門的評価に基づいて同意権を代行する</li></ul><h3 id="_2-4-最小損害原則" tabindex="-1">2.4 最小損害原則 <a class="header-anchor" href="#_2-4-最小損害原則" aria-label="Permalink to &quot;2.4 最小損害原則&quot;">​</a></h3><p>修練行動は可能な限り他人と環境への損害を避けるべきである。避けられない影響が生じる場合には、最も損害の少ない方法を選択し、生じた損害に対して合理的な補償を行わなければならない。具体的には以下を含む：</p><ul><li>修練実験は優先的に隔離空間で行い、リスクの拡散を防止する</li><li>戦闘類の修練はできるだけ専門の修練場で行い、公共環境への破壊を避ける</li><li>修練過程で生じたエネルギー汚染、空間損傷などを速やかに清掃・修復する</li><li>人口密集地で高リスクの修練活動を行うことを禁止する</li></ul><h3 id="_2-5-誠実不欺原則" tabindex="-1">2.5 誠実不欺原則 <a class="header-anchor" href="#_2-5-誠実不欺原則" aria-label="Permalink to &quot;2.5 誠実不欺原則&quot;">​</a></h3><p>修練者は修練関連事項において誠実さを保ち、虚偽の行動をしてはならない。具体的には以下を含む：</p><ul><li>修練境界、貢献値、考査成績などを偽造することを禁止する</li><li>修練心得、研究成果において虚偽または盗用することを禁止する</li><li>資源申請、プロジェクト申請において虚偽情報を提供することを禁止する</li><li>虚偽の約束で他人の修練資源や信頼をだまし取ることを禁止する</li></ul><h3 id="_2-6-責任担当原則" tabindex="-1">2.6 責任担当原則 <a class="header-anchor" href="#_2-6-責任担当原則" aria-label="Permalink to &quot;2.6 責任担当原則&quot;">​</a></h3><p>力が大きければ大きいほど、責任も大きくなる。高級修練者は自身の力に見合った公共責任を担わなければならない。具体的には以下を含む：</p><ul><li>一定の境界に達した修練者は初級修練者を指導する義務がある</li><li>高級修練者は錨点維護、文明守護などの公共事務に参加する義務がある</li><li>修練者は自身の修練行動がもたらした結果に責任を負い、責任転嫁してはならない</li><li>文明が危機に直面したとき、高級修練者は立ち上がる義務がある</li></ul><h2 id="第三節-修練の絶対禁忌" tabindex="-1">第三節 修練の絶対禁忌 <a class="header-anchor" href="#第三節-修練の絶対禁忌" aria-label="Permalink to &quot;第三節 修練の絶対禁忌&quot;">​</a></h2><p>以下の行動は修練の「絶対禁忌」に属し、いかなる修練者もいかなる状況下でも触れてはならず、違反者は最も厳しい制裁を受ける：</p><table tabindex="0"><thead><tr><th>禁忌タイプ</th><th>具体的行動</th><th>制裁措置</th></tr></thead><tbody><tr><td>本源略奪</td><td>他の生命の本源または生命核心を飲み込むまたは略奪する</td><td>修为廃止、終身監禁、情状が深刻な場合は本源消滅に処する</td></tr><tr><td>魂奴隷</td><td>魂制御、精神奴隷などの手段で他の生命を道具に変える</td><td>修为廃止、強制倫理改造、永久に修練権を剥奪</td></tr><tr><td>種族絶滅</td><td>修練を目的としてある種族に対し体系的な虐殺または絶滅を行う</td><td>錨点法院最高裁判、極刑に処する</td></tr><tr><td>位面破壊</td><td>資源または力を得るために位面全体を破壊する</td><td>極刑、かつ位面修復の全責任を負う</td></tr><tr><td>非人道的実験</td><td>智慧生命に対し非人道的な修練実験を行う</td><td>修为廃止、終身監禁、研究成果をすべて破棄</td></tr><tr><td>時間犯罪</td><td>時間遡及能力を利用して大規模な歴史改竄または殺人を行う</td><td>極刑、かつ永久に時間関連能力を剥奪</td></tr><tr><td>法則汚染</td><td>故意に宇宙本源法則を汚染し、宇宙全体に不可逆的損害を与える</td><td>極刑、かつ文明最高機構が法則浄化を実行</td></tr></tbody></table><p>絶対禁忌の設定は、共生文明の修練倫理の底線に対する断固たる立場を体現している。これらの禁忌には「グレーゾーン」はなく、「情状酌量の余地」もなく、絶対禁忌に触れるいかなる行動も最も厳しい制裁を受ける。</p><h2 id="第四節-修練倫理のグレーゾーンと処理原則" tabindex="-1">第四節 修練倫理のグレーゾーンと処理原則 <a class="header-anchor" href="#第四節-修練倫理のグレーゾーンと処理原則" aria-label="Permalink to &quot;第四節 修練倫理のグレーゾーンと処理原則&quot;">​</a></h2><p>明確な禁忌のほかに、修練倫理にはいくつかの「グレーゾーン」が存在する——これらの行動はそれ自体が絶対的な善または悪ではなく、その倫理的性質は具体的な状況、動機、方法、結果に依存する。グレーゾーンに対して、共生文明は以下の処理原則を採用する：</p><h3 id="_4-1-一般的なグレーゾーン" tabindex="-1">4.1 一般的なグレーゾーン <a class="header-anchor" href="#_4-1-一般的なグレーゾーン" aria-label="Permalink to &quot;4.1 一般的なグレーゾーン&quot;">​</a></h3><ul><li><strong>戦闘修練における損傷</strong>: 修練者は対戦訓練で互いに損傷を与える可能性があり、この損傷が倫理的かどうかは双方がインフォームド・コンセントを与えたかどうか、損傷が合理的範囲内かどうかに依存する</li><li><strong>資源競争</strong>: 修練者間の希少資源に対する競争が倫理的かどうかは、競争方法が公平かどうか、独占禁止規則を遵守しているかどうかに依存する</li><li><strong>師弟関係における権力の非対称性</strong>: 師弟間には生来の権力の非対称性が存在し、師が権力を濫用しているかどうかは具体的な判断が必要である</li><li><strong>修練におけるリスク負担</strong>: 一部の修練方法はそれ自体が高リスクであり、修練者が自発的にリスクを負担することが倫理的かどうかは、リスクの知情性と代替可能性の評価が必要である</li><li><strong>異種族修練協力</strong>: 異なる種族間の修練協力には文化的差異と権力の非対称性が関わる可能性があり、具体的な評価が必要である</li></ul><h3 id="_4-2-処理原則" tabindex="-1">4.2 処理原則 <a class="header-anchor" href="#_4-2-処理原則" aria-label="Permalink to &quot;4.2 処理原則&quot;">​</a></h3><p>グレーゾーンの倫理問題に対して、共生文明は「具体的状況分析＋倫理委員会評価＋先例指導」の処理方法を採用する：</p><ol><li><strong>具体的状況分析</strong>: 「一律に処理」せず、具体的な状況、動機、方法、結果に基づいて総合的に判断する</li><li><strong>倫理委員会評価</strong>: 複雑な倫理問題については、錨点法院傘下の「倫理委員会」に提出して専門的評価を行う</li><li><strong>先例指導</strong>: 倫理委員会の評価結果は先例を形成し、その後の類似事件に指導を提供する</li><li><strong>教育優先</strong>: グレーゾーンにおける不適切な行動に対しては、直接的な厳しい制裁ではなく、教育と矯正の方法を優先する</li><li><strong>動的調整</strong>: 文明の発展と倫理認識の深化に伴い、グレーゾーンの判断基準は動的に調整され得る</li></ol><h2 id="第五節-修練倫理の教育と内面化" tabindex="-1">第五節 修練倫理の教育と内面化 <a class="header-anchor" href="#第五節-修練倫理の教育と内面化" aria-label="Permalink to &quot;第五節 修練倫理の教育と内面化&quot;">​</a></h2><p>修練倫理の維持は外部の制裁と監督だけに依存することはできず、修練者が心の奥底から認同し内面化することがさらに必要である。共生文明は体系的な修練倫理教育体系を構築した：</p><h3 id="_5-1-基礎教育" tabindex="-1">5.1 基礎教育 <a class="header-anchor" href="#_5-1-基礎教育" aria-label="Permalink to &quot;5.1 基礎教育&quot;">​</a></h3><ul><li>修練倫理はすべての修練者の必修課程であり、感元境から始まって体系的な倫理教育を受けなければならない</li><li>教育内容には倫理原則、禁忌リスト、ケース分析、状況シミュレーションなどが含まれる</li><li>教育方法には教室授業、ケース討論、ロールプレイ、導師の言伝身教などが含まれる</li></ul><h3 id="_5-2-進階教育" tabindex="-1">5.2 進階教育 <a class="header-anchor" href="#_5-2-進階教育" aria-label="Permalink to &quot;5.2 進階教育&quot;">​</a></h3><ul><li>修練者の境界の向上に伴い、倫理教育の深度と広さも相応に向上する</li><li>高級修練者はより複雑な倫理問題（異位面倫理、時間倫理、創世倫理など）を学ぶ必要がある</li><li>道元境以上の修練者は「高階倫理考査」に合格して初めて境界の向上を継続できる</li></ul><h3 id="_5-3-実践内面化" tabindex="-1">5.3 実践内面化 <a class="header-anchor" href="#_5-3-実践内面化" aria-label="Permalink to &quot;5.3 実践内面化&quot;">​</a></h3><ul><li>修練者が日常の修練で倫理原則を実践し、倫理要求を自覚的な行動習慣に転化することを奨励する</li><li>「倫理模範」選挙制度を設立し、修練倫理の面で傑出した業績を示した修練者を表彰する</li><li>導師は修練技術を伝授すると同時に倫理精神を伝授する義務があり、「道术兼伝」を実現する</li></ul><h2 id="第六節-修練倫理の監督と執行" tabindex="-1">第六節 修練倫理の監督と執行 <a class="header-anchor" href="#第六節-修練倫理の監督と執行" aria-label="Permalink to &quot;第六節 修練倫理の監督と執行&quot;">​</a></h2><h3 id="_6-1-監督メカニズム" tabindex="-1">6.1 監督メカニズム <a class="header-anchor" href="#_6-1-監督メカニズム" aria-label="Permalink to &quot;6.1 監督メカニズム&quot;">​</a></h3><ul><li><strong>錨点ネットワーク監測</strong>: 錨点ネットワークは修練者の修練行動を継続的に監測し、倫理違反の疑いのある行動に対して速やかに预警する</li><li><strong>倫理告発制度</strong>: いかなる生命も錨点法院の倫理法廷に修練倫理に違反する行動を告発することができ、告発者は保護される</li><li><strong>定期倫理評価</strong>: 法元境以上の修練者は毎年1回の倫理評価を受ける必要があり、評価結果は個人修練档案に記録される</li><li><strong>社会組織監督</strong>: 各種修練者組織、種族コミュニティなどが構成員の修練倫理に対して内部監督を行うことを奨励する</li></ul><h3 id="_6-2-執行メカニズム" tabindex="-1">6.2 執行メカニズム <a class="header-anchor" href="#_6-2-執行メカニズム" aria-label="Permalink to &quot;6.2 執行メカニズム&quot;">​</a></h3><ul><li><strong>倫理法廷</strong>: 錨点法院傘下の専門倫理法廷が、修練倫理事件の審理を担当する</li><li><strong>段階的制裁</strong>: 倫理違反の深刻度に応じて、警告、罰金、貢献値控除、修練権限制限、修为廃止から終身監禁、極刑までの段階的制裁を実施する</li><li><strong>倫理改造</strong>: 悔改の意がある違反者に対しては、制裁と同時に倫理改造を行うことができ、改造が成功すれば権利を一部回復できる</li><li><strong>前科記録</strong>: 修練倫理違反の記録は永久に個人档案に記録され、その後の境界認定、資源分配、公共職位申請などに影響を与える</li></ul><h2 id="第七節-修練境界の動的拡張" tabindex="-1">第七節 修練境界の動的拡張 <a class="header-anchor" href="#第七節-修練境界の動的拡張" aria-label="Permalink to &quot;第七節 修練境界の動的拡張&quot;">​</a></h2><p>修練倫理と境界は不変の教条ではなく、文明の発展、技術の進歩、認識の深化に伴って動的に調整される生きた規範である。共生文明は修練境界の動的拡張メカニズムを構築した：</p><ol><li><strong>新技術倫理評価</strong>: 新しい修練技術または法則応用が出現するたびに、まず倫理評価を行い、評価に合格して初めて普及させることができる</li><li><strong>新場面倫理検討</strong>: 文明が新しい発展段階（異位面時代、星間時代など）に入るとき、専門の倫理検討を組織し、新しい場面に適応した倫理規範を制定する</li><li><strong>倫理規範定期改訂</strong>: 修練倫理の具体的な規範は50年ごとに1回改訂され、改訂過程ではすべての生命の意見を広く聴取する</li><li><strong>倫理先例の継続的蓄積</strong>: 倫理法廷の判決は先例を形成し、修練倫理の具体的な内包を継続的に豊かにし細分化する</li></ol><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>修練倫理と境界は錨点共生文明の精神文明の核心的支柱である。それは根本的な問題に答える：「修練者はどのような人間になるべきか？」共生文明の答えは：修練者は力を持ち、さらに道徳を持つ人間になるべきである；個人の進化と万族共生を統一した人間になるべきである；力を追求するが決して力に奴隷化されない人間になるべきである。修練倫理は力に対する束縛ではなく、力に対する昇華である——それは力が常に生命の尊厳と文明の進歩に奉仕し、破壊と略奪の道具にならないことを確保する。力が山を移し海を埋め、世界を創り滅ぼすことができる宇宙において、修練倫理は文明の底線を守る最後の、そして最も重要な防衛線である。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (反略奪主義核心論綱)</li><li>17-位面至高强者标准 (位面至高強者基準)</li><li>48-司法体系与裁决机制 (司法体系と裁決メカニズム)</li></ul>',56)])])}const _=a(e,[["render",o]]);export{b as __pageData,_ as default};
